  "items": [
    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 현상인 괴사와 세포자멸사를 죽음이 일어나는 방식이라는 같은 기준에서 대조한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "올챙이의 꼬리 소실은 불필요한 세포를 제거하는 세포자멸사의 구체적인 사례이다."
    },
    {
      "id": "R3",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "비정상적 세포를 제거하여 신체를 보호한다는 사실이 세포자멸사가 적절히 일어나야 한다는 당위의 근거이다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "손상된 세포를 제거한다는 설명을 Bcl-2 감소와 카스파제 활성화 등의 세부 기전으로 구체화한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "해로운 비정상적 세포의 제거를 바이러스 감염 세포에 대한 세포독성 T세포의 작용 사례로 구체화한다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자외선에 의한 DNA 손상은 Bcl-2 감소를 설명하면서 제시한 세포 손상의 구체적인 사례이다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "호르몬 부족은 Bcl-2 감소에 앞서는 세포 손상의 구체적인 경우로 제시된다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포 손상으로 감소한 Bcl-2가 미토콘드리아 막 파괴로 이어지는 실제 작용 관계이다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "Bcl-2가 세포자멸사를 억제한다는 기능적 사실이 그 감소로 자멸사 과정이 진행되는 이유를 뒷받침한다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아 막의 파괴가 내부 물질의 방출을 실제로 일으킨다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "미토콘드리아에서 방출된 물질이 카스파제의 활성화를 실제로 일으킨다."
    },
    {
      "id": "R12",
      "type": "PROCESS",
      "otherName": "",
      "reason": "카스파제-9가 먼저 활성화된 다음 실행 카스파제를 활성화하는 단계의 차례를 연결한다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "카스파제-9에 의해 활성화된 실행 카스파제가 DNA 절단과 붕괴를 일으키는 작용의 연쇄이다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "세포자멸사 유도 경로라는 같은 기준에서 Bcl-2·미토콘드리아 경로와 세포독성 T세포·과립효소 B 경로의 차이를 보여 준다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "감염 세포 표면에 나타난 바이러스 단백질을 다음 단계에서 세포독성 T세포가 인식하는 과정이다."
    },
    {
      "id": "R16",
      "type": "PROCESS",
      "otherName": "",
      "reason": "바이러스 단백질을 비정상으로 인식한 뒤 감염 세포에 결합하는 처리 단계의 순서를 나타낸다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포독성 T세포가 감염 세포에 결합한 다음 구멍을 뚫는 단백질을 분비하는 순서이다."
    },
    {
      "id": "R18",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 분비된 단백질이 만든 구멍을 이용해 다음 단계의 과립효소 B 유입이 진행된다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "감염 세포 안으로 들어간 과립효소 B가 실행 카스파제의 활성화를 일으킨다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "과립효소 B에 의해 활성화된 실행 카스파제가 감염 세포의 DNA 붕괴를 일으킨다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "실행 카스파제가 DNA를 붕괴시킨다는 일반적 작용을 과립효소 B로 활성화된 감염 세포의 경우로 구체화한다."
    },
    {
      "id": "R22",
      "type": "PROCESS",
      "otherName": "",
      "reason": "실행 카스파제 활성화와 DNA 붕괴에 이어 형태 변화와 식세포에 의한 제거가 진행되는 전체 과정의 순서를 연결한다."
    },
    {
      "id": "R23",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실행 카스파제에 의한 DNA 붕괴가 DNA의 사다리 모양 출현으로 이어진다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "감염 세포에서 실행 카스파제가 일으킨 DNA 붕괴가 사다리 모양이라는 특징으로 이어진다."
    },
    {
      "id": "R25",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포 수축이 먼저 나타나고 이후 세포 파편화가 일어나는 순서를 설명한다."
    },
    {
      "id": "R26",
      "type": "PROCESS",
      "otherName": "",
      "reason": "핵 분절에 이어 세포 파편화가 나타나는 단계의 차례이며 직접적인 인과는 제시되지 않는다."
    },
    {
      "id": "R27",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포 파편화 이후 세포막의 두 층이 뒤섞인다는 시간적 순서를 명시한다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세포막 두 층의 뒤섞임이 포스파티딜세린의 바깥쪽 노출로 이어지는 실제 변화이다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "바깥으로 노출된 포스파티딜세린이 식세포의 자멸사 세포 인식을 일으킨다고 명시한다."
    },
    {
      "id": "R30",
      "type": "PROCESS",
      "otherName": "",
      "reason": "식세포가 자멸사한 세포를 인식한 다음 그 세포를 포식하는 처리 순서이다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "식세포의 포식을 염증 유발 물질이 새어 나오기 전에 신속히 이루어지는 처리라고 더 자세히 설명한다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "염증 유발 물질이 유출되기 전의 신속한 세포 제거가 염증 반응을 막는 실제 기전이다."
    },
    {
      "id": "R33",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "세포자멸사와 괴사를 구별하는 논의를 죽음의 방식에서 염증 유발 여부로 넓힌다."
    },
    {
      "id": "R34",
      "type": "CAUSE",
      "otherName": "",
      "reason": "비정상적 세포의 적시 제거가 새로운 세포의 생성으로 이어진다고 설명한다."
    },
    {
      "id": "R35",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "비정상적 세포 제거의 의의를 질병으로부터의 신체 보호에서 새로운 세포의 생성으로 확장한다."
    },
    {
      "id": "R36",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞에서 설명한 세포자멸사의 기전을 악성 종양 등 질병 치료라는 다른 영역에 활용하는 연구이다."
    }
  ]
}

